// Seven root-neighbor columns; a triple is encoded by a bit among 35 positions.
use std::io::{self,BufRead};
fn patterns(rest:u8,mask:u128,out:&mut Vec<u128>){if rest==0{out.push(mask);return}let i=rest&rest.wrapping_neg();let mut b=rest^i;while b!=0{let j=b&b.wrapping_neg();b^=j;let mut next=mask;for t in 0..128{if (t as u8&(i|j)).count_ones()!=1{next&=!(1u128<<t)}}patterns(rest^i^j,next,out)}}
fn main(){let list=std::env::args().nth(1).as_deref()==Some("--seven");let mut pats=vec![];for exc in 0..7{patterns(127^(1<<exc),u128::MAX,&mut pats)}assert_eq!(pats.len(),105);let mut h=[0u64;9];let mut best=0;let mut ex=(0,0,0,0);for (idx,l) in io::stdin().lock().lines().enumerate(){let l=l.unwrap();let b=l.as_bytes();let mut a=[0u32;27];let mut k=0;for j in 0..27{for i in 0..j{if (b[1+k/6]-63)>>(5-k%6)&1==1{a[i]|=1<<j;a[j]|=1<<i}k+=1}}for v in 0..27{let ns=a[v];if ns.count_ones()!=7{continue}let mut b=ns;let mut perm=[0;27];let mut t=1u8;while b!=0{perm[b.trailing_zeros() as usize]=t;t<<=1;b&=b-1}let mut available=0u128;for u in 0..27{if u==v||ns>>u&1!=0{continue}let mut z=a[u]&ns;if z.count_ones()!=3{continue}let mut code=0;while z!=0{code|=perm[z.trailing_zeros() as usize];z&=z-1}available|=1u128<<code}let mut local=0;for (p,m) in pats.iter().enumerate(){let n=(m&available).count_ones();local=local.max(n);if n>best{best=n;ex=(idx+1,v,p,available)}}h[local as usize]+=1;if list&&local==7{eprintln!("{} {}",idx+1,v)}}}println!("{:?}\n{:?}",h,ex)}
